// ../flow-tool/src/services/flow-eval-run-format.ts
function formatDuration(durationMs) {
  if (durationMs === null || durationMs === undefined) {
    return "-";
  }
  return `${(durationMs / 1000).toFixed(1)}s`;
}
function formatEvaluatorScores(scores, evaluators) {
  if (!scores || scores.length === 0) {
    return "-";
  }
  return scores.map((score) => {
    const evaluator = evaluators.find((item) => item.id === score.evaluatorId);
    return `${evaluator?.name ?? score.evaluatorId}: ${score.value}`;
  }).join(", ");
}
function evaluatorSnapshotName(snapshot) {
  if (typeof snapshot === "object" && snapshot !== null && !Array.isArray(snapshot) && typeof snapshot.name === "string") {
    return snapshot.name;
  }
  return;
}
function remoteEvaluatorName(evaluatorId, evaluatorSnapshot, evaluators) {
  return evaluators.find((item) => item.id === evaluatorId)?.name ?? evaluatorSnapshotName(evaluatorSnapshot) ?? evaluatorId;
}
function remoteRunScore(run) {
  if (run.result?.scores && run.result.scores.length > 0) {
    const sum = run.result.scores.reduce((total, score) => total + score.value, 0);
    return Number((sum / run.result.scores.length).toFixed(4));
  }
  const value = run.result?.score?.value;
  return typeof value === "number" || typeof value === "boolean" ? value : "-";
}
function formatRemoteEvalRunRow(run, evaluators, verbose = false) {
  let evaluatorScores = "-";
  let justifications = "-";
  if (run.evaluatorRuns && run.evaluatorRuns.length > 0) {
    evaluatorScores = run.evaluatorRuns.map((evaluatorRun) => {
      const name = remoteEvaluatorName(evaluatorRun.evaluatorId, evaluatorRun.evaluatorSnapshot, evaluators);
      const score = evaluatorRun.result?.score;
      if (score?.type === "error") {
        return `${name}: Error`;
      }
      return `${name}: ${score?.value ?? "-"}`;
    }).join(", ");
    const justificationParts = run.evaluatorRuns.filter((evaluatorRun) => evaluatorRun.result?.score?.justification).map((evaluatorRun) => {
      const name = remoteEvaluatorName(evaluatorRun.evaluatorId, evaluatorRun.evaluatorSnapshot, evaluators);
      return `[${name}] ${evaluatorRun.result?.score?.justification}`;
    });
    if (justificationParts.length > 0) {
      justifications = justificationParts.join(" | ");
    }
  } else if (run.result?.scores && run.result.scores.length > 0) {
    evaluatorScores = formatEvaluatorScores(run.result.scores, evaluators);
  }
  const tokens = run.completionMetrics?.tokens;
  const duration = run.completionMetrics?.duration;
  const error = run.errorMessage ?? (typeof run.error === "string" ? run.error : run.error?.message) ?? "-";
  const row = {
    DataPoint: run.evalSnapshot?.name ?? run.id,
    Status: run.status,
    Score: remoteRunScore(run),
    EvaluatorScores: evaluatorScores,
    Tokens: typeof tokens === "number" && tokens > 0 ? tokens : "-",
    Duration: typeof duration === "number" ? formatDuration(duration) : "-",
    Error: error
  };
  if (verbose) {
    row.Justifications = justifications;
  }
  return row;
}
function isFailedRemoteRun(run) {
  const status = run.status.toLowerCase();
  if (status === "failed" || status === "workloadfailed" || run.errorMessage || run.error) {
    return true;
  }
  if (run.result?.score?.type === "error") {
    return true;
  }
  return run.evaluatorRuns?.some((evaluatorRun) => evaluatorRun.result?.score?.type === "error" || evaluatorRun.result?.score?.value === false) ?? false;
}
function isTerminalRemoteStatus(status) {
  return ["completed", "partiallycompleted", "failed"].includes(status.toLowerCase());
}
function formatEvalSetRunRow(run, evaluators) {
  return {
    EvalSetRunId: run.id,
    Status: run.status,
    Score: run.score ?? "-",
    DataPoints: run.numberOfEvalsExecuted ?? "-",
    Duration: formatDuration(run.durationMilliseconds),
    EvaluatorScores: formatEvaluatorScores(run.evaluatorScores, evaluators),
    CreatedAt: run.createdAt
  };
}

