function buildComparison(evalSetRunId, compareTo, runMetaA, runMetaB, runsA, runsB) {
  const runsBByName = new Map;
  for (const run of runsB) {
    runsBByName.set(run.evalSnapshot?.name ?? run.id, run);
  }
  const dataPoints = runsA.map((runA) => {
    const name = runA.evalSnapshot?.name ?? runA.id;
    const runB = runsBByName.get(name);
    const scoreA = remoteRunScore(runA);
    const scoreB = runB ? remoteRunScore(runB) : "-";
    let delta = "-";
    if (typeof scoreA === "number" && typeof scoreB === "number") {
      delta = Number((scoreA - scoreB).toFixed(4));
    }
    return {
      DataPoint: name,
      ScoreA: scoreA,
      ScoreB: scoreB,
      Delta: delta,
      StatusA: runA.status,
      StatusB: runB?.status ?? "-"
    };
  });
  return {
    RunA: {
      Id: evalSetRunId,
      Score: runMetaA.score ?? "-",
      Status: runMetaA.status
    },
    RunB: {
      Id: compareTo,
      Score: runMetaB.score ?? "-",
      Status: runMetaB.status
    },
    ScoreDelta: typeof runMetaA.score === "number" && typeof runMetaB.score === "number" ? Number((runMetaA.score - runMetaB.score).toFixed(4)) : "-",
    DataPoints: dataPoints
  };
}

