function parsePosition2(value) {
  const parts = value.split(",");
  if (parts.length !== 2) {
    throw new Error(`Invalid position format: "${value}". Expected "x,y" (e.g. 250,150)`);
  }
  const x = Number(parts[0]);
  const y = Number(parts[1]);
  if (Number.isNaN(x) || Number.isNaN(y)) {
    throw new Error(`Invalid position values: "${value}". x and y must be numbers`);
  }
  return { x, y };
}
function getDeleteNodeInstructions(file) {
  return `Check that "${file}" exists and run 'uip maestro flow node list ${file}' to find a valid node ID, then retry.`;
}
async function runDeleteNode(file, nodeId, code) {
  const { deleteNodeFromFlow } = await import("./node-service-teagjd9n.js");
  const normalizedNodeId = nodeId.trim();
  const [error, result] = await catchError(deleteNodeFromFlow(file, normalizedNodeId));
  if (error) {
    OutputFormatter.error({
      Result: RESULTS.Failure,
      Message: "Error deleting node",
      Instructions: getDeleteNodeInstructions(file)
    });
    processContext.exit(1);
    return;
  }
  OutputFormatter.success({
    Result: RESULTS.Success,
    Code: code,
    Data: {
      DeletedNode: result.deletedNode,
      EdgesRemoved: result.edgesRemoved,
      BindingsRemoved: result.bindingsRemoved,
      DefinitionsRemoved: result.definitionsRemoved,
      VariablesRemoved: result.variablesRemoved,
      VariableUpdatesRemoved: result.variableUpdatesRemoved
    }
  });
}
