// ../flow-tool/src/commands/tidy.ts
var registerTidyCommand = (program) => {
  program.command("format").description("Format a .flow file by auto-laying out nodes to prevent overlaps and arrange in a clean flow").argument("<file>", "Path to the .flow file").trackedAction(processContext, async (file) => {
    const { tidyFlow } = await import("./tidy-service-hc9gex0v.js");
    const [error, result] = await catchError(tidyFlow(file));
    if (error) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Failed to tidy flow",
        Instructions: error.message
      });
      processContext.exit(1);
      return;
    }
    const changes = [];
    if (result.nodesRepositioned > 0) {
      changes.push(`Repositioned ${result.nodesRepositioned} of ${result.nodeCount} nodes`);
    }
    if (result.nodesResized > 0) {
      changes.push(`Set canonical size on ${result.nodesResized} node(s)`);
    }
    if (result.subflowsTidied > 0) {
      changes.push(`Tidied ${result.subflowsTidied} subflow(s)`);
    }
    OutputFormatter.success({
      Result: RESULTS.Success,
      Code: "FlowFormat",
      Data: {
        File: file,
        NodesTotal: result.nodeCount,
        EdgesTotal: result.edgeCount,
        NodesRepositioned: result.nodesRepositioned,
        NodesResized: result.nodesResized,
        SubflowsTidied: result.subflowsTidied,
        VariableCount: result.variableCount
      },
      Instructions: changes.length > 0 ? changes.join(". ") : "All nodes already in optimal positions"
    });
  });
};

