// ../flow-tool/src/services/project-metadata-reader.ts
async function readAgentProjectMetadata(projectDir) {
  const fs = getFileSystem();
  const [readError, content] = await catchError(fs.readFile(fs.path.join(projectDir, "agent.json"), "utf-8"));
  if (readError || typeof content !== "string") {
    logger.debug(`No readable agent.json in ${projectDir}; the node will describe an autonomous agent.`);
    return {};
  }
  const [parseError, parsed] = catchError(() => JSON.parse(content));
  if (parseError) {
    logger.debug(`Unparseable agent.json in ${projectDir}: ${parseError.message}. The node will describe an autonomous agent.`);
    return {};
  }
  const metadata = {};
  const isConversational = parsed.metadata?.isConversational;
  if (typeof isConversational === "boolean") {
    metadata.isConversational = isConversational;
  }
  const targetRuntime = parsed.metadata?.targetRuntime;
  if (typeof targetRuntime === "string") {
    metadata.targetRuntime = targetRuntime;
  }
  return metadata;
}
var agentProjectMetadataReader = (projectDir, projectType) => projectType === "Agent" ? readAgentProjectMetadata(projectDir) : Promise.resolve({});

